import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

function expandInstancedMeshes(object) {
    const instancedMeshes = [];
    object.traverse(child => {
        if (child.isInstancedMesh) {
            instancedMeshes.push(child);
        }
    });

    instancedMeshes.forEach(instancedMesh => {
        const parent = instancedMesh.parent;
        const count = instancedMesh.count;
        const geometry = instancedMesh.geometry;
        const material = instancedMesh.material;

        for (let i = 0; i < count; i++) {
            const mesh = new THREE.Mesh(geometry, material);
            const matrix = new THREE.Matrix4();
            instancedMesh.getMatrixAt(i, matrix);

            // Apply the instance matrix to the new mesh
            mesh.applyMatrix4(matrix);
            mesh.name = `${instancedMesh.name}_${i}`;
            parent.add(mesh);
        }
        parent.remove(instancedMesh);
    });
}

try {
    // Create the scene
    const root = createScene();

    // Expand InstancedMeshes because OBJExporter might not support them
    expandInstancedMeshes(root);

    // Requirements: Blender Z-up space by applying a -90 degrees X-rotation
    // Three.js is Y-up. Blender is Z-up.
    // Rotating the root object -90 degrees around X will make the Y-up geometry point along the Z-axis.
    root.rotation.x = -Math.PI / 2;

    // We need to update world matrices before exporting
    root.updateMatrixWorld(true);

    // Export to OBJ
    const exporter = new OBJExporter();
    const result = exporter.parse(root);

    // Ensure output directory exists
    const outputDir = '/root/output';
    if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir, { recursive: true });
    }

    // Write to file
    fs.writeFileSync(path.join(outputDir, 'object.obj'), result);

    console.log('Successfully exported to /root/output/object.obj');
} catch (error) {
    console.error('Error during export:', error);
    process.exit(1);
}

